+using Clm.Api.Services;
+
+namespace Clm.Api.Validation
+{
+    public interface IRenewalValidator
+    {
+        ValidationResult Validate(Agreement agreement, RenewRequest request);
+    }
+
+    public class RenewalValidator : IRenewalValidator
+    {
+        private readonly IFeatureFlagService _features;
+
+        public RenewalValidator(IFeatureFlagService features)
+        {
+            _features = features;
+        }
+
+        public ValidationResult Validate(Agreement agreement, RenewRequest request)
+        {
+            if (!_features.IsFeatureEnabled("clm.renewal.preValidation"))
+            {
+                return ValidationResult.Success;
+            }
+            if (agreement.Status == "Terminated" || agreement.Status == "Expired")
+            {
+                return ValidationResult.Fail("Renewal is not allowed for terminated or expired agreements");
+            }
+            if (request.TermMonths.HasValue && request.TermMonths <= 0)
+            {
+                return ValidationResult.Fail("Renewal term must be positive");
+            }
+            return ValidationResult.Success;
+        }
+    }
+}

